package stud.g01.heuristic;

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.CRC32;

/**
 * Additive disjoint databases generated by reverse BFS. Non-pattern tiles, including the blank, are
 * indistinguishable empty cells. Moving one pattern tile into an adjacent empty cell costs one.
 * Every real move projects to cost one in exactly one group (zero in the others), so the sum is
 * admissible and consistent. Allowing the abstract blank to move freely is a relaxation.
 */
final class PatternDatabase {
  private static final int MAGIC = 0x50444232;
  private static final Map<String, Pattern> LOADED = new HashMap<>();

  static final class Pattern {
    final byte[] distances;

    Pattern(byte[] distances) {
      this.distances = distances;
    }

    int distance(int index) {
      return distances[index] & 255;
    }
  }

  static synchronized Pattern load(int size, int[] goalPositions) {
    String key =
        size + "-" + Arrays.toString(goalPositions).replaceAll("[\\[\\] ]", "").replace(',', '_');
    if (LOADED.containsKey(key)) return LOADED.get(key);
    Path directory = Paths.get(System.getProperty("lab.pdbCache", ".cache/pdb"));
    Path file = directory.resolve("relaxed-v2-" + key + ".bin");
    int length = 1 << (4 * goalPositions.length);
    byte[] distances = null;
    long start = System.nanoTime();
    String operation = "load";
    if (Files.isRegularFile(file))
      try (DataInputStream in =
          new DataInputStream(new BufferedInputStream(Files.newInputStream(file)))) {
        if (in.readInt() != MAGIC || in.readInt() != length)
          throw new IOException("header mismatch");
        long checksum = in.readLong();
        distances = in.readNBytes(length);
        CRC32 crc = new CRC32();
        crc.update(distances);
        if (distances.length != length || crc.getValue() != checksum)
          throw new IOException("checksum mismatch");
      } catch (IOException e) {
        distances = null;
        System.err.println("PDB cache ignored: " + e.getMessage());
      }
    if (distances == null) {
      operation = "build";
      distances = build(size, goalPositions, length);
      try {
        Files.createDirectories(directory);
        Path temporary = Files.createTempFile(directory, "pdb-", ".tmp");
        CRC32 crc = new CRC32();
        crc.update(distances);
        try (DataOutputStream out =
            new DataOutputStream(new BufferedOutputStream(Files.newOutputStream(temporary)))) {
          out.writeInt(MAGIC);
          out.writeInt(length);
          out.writeLong(crc.getValue());
          out.write(distances);
        }
        Files.move(temporary, file, StandardCopyOption.REPLACE_EXISTING);
      } catch (IOException e) {
        System.err.println("PDB cache not saved: " + e.getMessage());
      }
    }
    Pattern result = new Pattern(distances);
    LOADED.put(key, result);
    System.err.printf(
        Locale.ROOT,
        "PDB %s %s: %.3f s, %.2f MiB%n",
        operation,
        key,
        (System.nanoTime() - start) / 1e9,
        length / 1048576.0);
    return result;
  }

  private static byte[] build(int size, int[] goal, int length) {
    int cells = size * size, k = goal.length, total = 1;
    for (int i = 0; i < k; i++) total *= cells - i;
    byte[] distances = new byte[length];
    Arrays.fill(distances, (byte) 255);
    int[] queue = new int[total], adjacency = new int[cells];
    for (int p = 0; p < cells; p++) {
      if (p >= size) adjacency[p] |= 1 << (p - size);
      if (p + size < cells) adjacency[p] |= 1 << (p + size);
      if (p % size > 0) adjacency[p] |= 1 << (p - 1);
      if (p % size + 1 < size) adjacency[p] |= 1 << (p + 1);
    }
    int root = 0;
    for (int i = 0; i < k; i++) root |= goal[i] << (i * 4);
    int head = 0, tail = 1;
    queue[0] = root;
    distances[root] = 0;
    while (head < tail) {
      int state = queue[head++], occupancy = 0;
      for (int i = 0; i < k; i++) occupancy |= 1 << ((state >>> (i * 4)) & 15);
      int d = (distances[state] & 255) + 1;
      for (int i = 0; i < k; i++) {
        int shift = i * 4, p = (state >>> shift) & 15, moves = adjacency[p] & ~occupancy;
        while (moves != 0) {
          int q = Integer.numberOfTrailingZeros(moves);
          moves &= moves - 1;
          int next = state ^ ((p ^ q) << shift);
          if (distances[next] == (byte) 255) {
            distances[next] = (byte) d;
            queue[tail++] = next;
          }
        }
      }
    }
    if (tail != total) throw new IllegalStateException("Incomplete PDB: " + tail + "/" + total);
    return distances;
  }
}
